## 3. Codificação em Java

```java
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int L = fs.nextInt();
        int C = fs.nextInt();

        long ans = Math.max(L, C);

        if (L >= 2 && C >= 2) {
            int C1 = C - 1;

            long[] d1 = new long[C1];
            long[] d2 = new long[C1];

            // Lê a primeira linha e calcula D[0][c]
            long prev = fs.nextInt();
            for (int c = 0; c < C1; c++) {
                long val = fs.nextInt();
                d1[c] = val - prev;
                prev = val;
            }

            int[] heights = new int[C1];
            int[] stack = new int[C1 + 1];

            for (int i = 1; i < L; i++) {
                // Lê a linha i e calcula D[i][c]
                prev = fs.nextInt();
                for (int c = 0; c < C1; c++) {
                    long val = fs.nextInt();
                    d2[c] = val - prev;
                    prev = val;
                }

                // Atualiza alturas: condição D[i][c] <= D[i-1][c] => d2 <= d1
                for (int c = 0; c < C1; c++) {
                    if (d2[c] <= d1[c]) {
                        heights[c]++;
                    } else {
                        heights[c] = 0;
                    }
                }

                // Calcula o maior retângulo no histograma
                int top = -1;
                for (int c = 0; c <= C1; c++) {
                    int cur = (c == C1) ? -1 : heights[c];
                    while (top >= 0 && heights[stack[top]] >= cur) {
                        int h = heights[stack[top]];
                        top--;
                        int left = (top >= 0) ? stack[top] : -1;
                        int width = c - left - 1;
                        long cand = (long) (h + 1) * (width + 1);
                        if (cand > ans) ans = cand;
                    }
                    if (c < C1) {
                        stack[++top] = c;
                    }
                }

                // Troca d1 e d2 para a próxima iteração
                long[] tmp = d1;
                d1 = d2;
                d2 = tmp;
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
```

